<?php require 'config.php'; $error=''; if(isset($_GET['logout'])){session_destroy();header('Location: admin.php');exit;} if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){if(hash_equals(ADMIN_USER,$_POST['user']??'')&&hash_equals(ADMIN_PASS,$_POST['pass']??'')){$_SESSION['admin']=true;header('Location: admin.php');exit;}$error='Λάθος στοιχεία σύνδεσης.';} if(!logged_in()){$pageTitle='Σύνδεση';require 'header.php';?><form class="panel login" method="post"><h1>Διαχείριση</h1><?php if($error):?><p class="alert"><?=esc($error)?></p><?php endif?><label>Όνομα χρήστη<input name="user" required></label><label>Κωδικός<input type="password" name="pass" required></label><button class="primary" name="login">Σύνδεση</button><small>Αρχικά στοιχεία: admin / change-me-now</small></form><?php require 'footer.php';exit;}
$articles=load_json('articles.json');$sectors=load_json('sectors.json');
if(isset($_GET['delete'])){$articles=array_values(array_filter($articles,fn($a)=>$a['id']!==$_GET['delete']));save_json('articles.json',$articles);header('Location: admin.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save'])){$image='';if(!empty($_FILES['image']['name'])&&$_FILES['image']['error']===UPLOAD_ERR_OK){$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=mime_content_type($_FILES['image']['tmp_name']);if(isset($allowed[$mime])){$image='uploads/'.uniqid('article-',true).'.'.$allowed[$mime];move_uploaded_file($_FILES['image']['tmp_name'],__DIR__.'/'.$image);}}$articles[]=['id'=>slugify($_POST['title']),'title'=>trim($_POST['title']),'excerpt'=>trim($_POST['excerpt']),'sector'=>$_POST['sector'],'author'=>trim($_POST['author']),'date'=>$_POST['date'],'image'=>$image,'content'=>clean_article_html($_POST['content'])];save_json('articles.json',$articles);header('Location: admin.php?saved=1');exit;}
$pageTitle='Διαχείριση';require 'header.php';?>
<div class="admin-head"><h1>Διαχείριση άρθρων</h1><a href="?logout=1">Αποσύνδεση</a></div><div class="admin-grid"><form class="panel" method="post" enctype="multipart/form-data"><h2>Νέο άρθρο</h2><label>Τίτλος<input name="title" required></label><label>Σύντομη εισαγωγή<textarea name="excerpt" rows="3" required></textarea></label><label>Τομέας<select name="sector"><?php foreach($sectors as $s):?><option><?=esc($s)?></option><?php endforeach?></select></label><div class="two"><label>Συντάκτης<input name="author" required></label><label>Ημερομηνία<input type="date" name="date" value="<?=date('Y-m-d')?>" required></label></div><label>Κεντρική εικόνα<input type="file" name="image" accept="image/png,image/jpeg,image/webp"></label><label>Κείμενο άρθρου <small>(γράψτε κανονικά και αφήστε μία κενή γραμμή ανάμεσα στις παραγράφους)</small><textarea name="content" rows="12" placeholder="Πρώτη παράγραφος…&#10;&#10;Δεύτερη παράγραφος…" required></textarea></label><button class="primary" name="save">Δημοσίευση</button></form><section class="panel"><h2>Δημοσιευμένα</h2><?php foreach(array_reverse($articles) as $a):?><div class="admin-item"><div><b><?=esc($a['title'])?></b><small><?=esc($a['sector'])?></small></div><a class="danger" onclick="return confirm('Διαγραφή άρθρου;')" href="?delete=<?=urlencode($a['id'])?>">Διαγραφή</a></div><?php endforeach?></section></div><?php require 'footer.php'; ?>